// Triage router: evidence in, path out (runs in your Node project)
// Layers come from pdf.js getTextContent (Ch.2) or pdftotext probes.
function routePage(evidence) {
  if (evidence.textChars === 0) return "ocr";                    // scanned
  if (!evidence.embeddedFonts) return "ocr-fallback";          // broken encoding likely
  if (evidence.textChars < 50) return "inspect-manually";      // suspicious page
  return "text-extract";                                       // text-native
}
// Dossier entry: { pages: "12-40", class: "text-native", path: "text-extract" }

